from flask import Flask, Blueprint, jsonify

# Create a Blueprint for users routes
users_bp = Blueprint('users', __name__)

@users_bp.route('/', methods=['GET'])
def list_users():
    return jsonify({'users': ['alice', 'bob', 'charlie']})

@users_bp.route('/<int:user_id>', methods=['GET'])
def get_user(user_id):
    return jsonify({'user_id': user_id, 'name': f'User {user_id}'})

@users_bp.route('/', methods=['POST'])
def create_user():
    return jsonify({'message': 'User created'}), 201

@users_bp.route('/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    return jsonify({'user_id': user_id, 'message': 'User updated'})

@users_bp.route('/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    return jsonify({'user_id': user_id, 'message': 'User deleted'})

# Create the main Flask application
app = Flask(__name__)

# Register the users blueprint with /users prefix
app.register_blueprint(users_bp, url_prefix='/users')

@app.route('/', methods=['GET'])
def index():
    return jsonify({'message': 'Welcome to the API', 'endpoints': {
        'users': '/users',
        'user_detail': '/users/<id>',
    }})

if __name__ == '__main__':
    app.run(debug=True, port=5000)

